export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g;
  const t = sdk.clamp(time, 0, T);
  const y = u * t - g * t * t / 2;
  const v = u - g * t;
  const ya = u * u / (2 * g);
  const F = m * g;
  let st = 'Ready to toss';
  if (t <= 0) st = 'Ready to toss';
  else if (t >= T - 1e-9) st = 'Back at launch height';
  else if (Math.abs(t - ta) < 0.005) st = 'At the top';
  else if (t < ta) st = 'Rising';
  else st = 'Falling';
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 34, w: 300, h: 376, title: 'The motion', state: st }));
  o.push(sdk.axis('axis.h', { x: 70, y: 380, length: 300, orientation: 'y', min: 0, max: 2.2, ticks: [0, 0.5, 1, 1.5, 2], label: 'Height', unit: 'm' }));
  const by = 380 - y / 2.2 * 300;
  const bx = 150;
  o.push(sdk.circle('ball.toss', bx, by, 26));
  o.push(...sdk.vector('vec.v', { x: bx, y: by }, { value: v, direction: 'up' }, { scale: 14, label: 'v' }));
  o.push(...sdk.vector('vec.a', { x: bx + 30, y: by }, { value: -g, direction: 'up' }, { scale: 4, label: 'a' }));
  o.push(...sdk.callout(200, 120, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s²', 'F = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const pts = [];
  for (let i = 0; i <= 12; i++) { const tt = 1.8 * i / 12; const vv = u - g * tt; if (Math.abs(vv) <= 5.5) pts.push({ x: tt, y: vv }); }
  const cur = [];
  const n = 12;
  for (let i = 0; i <= n; i++) { const tt = t * i / n; cur.push({ x: tt, y: u - g * tt }); }
  o.push(sdk.plot('plot.vt', { x: 380, y: 50, w: 250, h: 300, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series: [{ label: 'v = u - g t', kind: 'line', points: pts }, { label: 'so far', kind: 'line', points: cur }] }));
  o.push(sdk.text('plot.vt.note', 505, 395, 'slope a = -g = ' + sdk.format(-g, 1) + ' m/s²', { align: 'middle' }));
  return {
    frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] },
    quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: ya, height: y, velocity: v, acceleration: -g, force: F }
  };
}
